import json
import math
import random

with open("/app/rules.json") as f:
    rules = json.load(f)
with open("/app/map.json") as f:
    world = json.load(f)
with open("/app/matrix_eco.json") as f:
    mat = json.load(f)

T, E = mat["T"], mat["E"]
base = world["base"]
targets = world["targets"]

nodes = [{"id": "base", "x": base[0], "y": base[1], "value": 0.0, "late_value": 0.0, "deadline_tick": None}]
for t in sorted(targets, key=lambda x: int(x["id"][1:])):
    nodes.append(t)
N = len(nodes)
id_to_idx = {n["id"]: i for i, n in enumerate(nodes)}

SOLAR_UNIT = [
    rules["solar_peak"] * math.sin(
        math.pi * (tick + rules["sun_margin_ticks"]) / (rules["max_ticks"] + 2 * rules["sun_margin_ticks"])
    )
    for tick in range(600)
]
SOLAR_UNIT_PREFIX = [0.0] * 601
for i in range(600):
    SOLAR_UNIT_PREFIX[i + 1] = SOLAR_UNIT_PREFIX[i] + SOLAR_UNIT[i]

def solar_sum(t1, t2, eff):
    i1 = max(0, min(599, int(t1)))
    i2 = max(0, min(599, int(t2)))
    if i1 == i2:
        return SOLAR_UNIT[i1] * eff * (t2 - t1)
    s1 = SOLAR_UNIT_PREFIX[i1] + (t1 - i1) * SOLAR_UNIT[i1]
    s2 = SOLAR_UNIT_PREFIX[i2] + (t2 - i2) * SOLAR_UNIT[i2]
    return (s2 - s1) * eff

def eval_eco(seq, eff=0.85, start_tick=4.0, overhead=1.6, max_ret=388.0, dl_margin=5.0, min_bat_floor=18.0):
    t = start_tick
    u = 0
    bat = 99.8
    score = 0.0
    total_wait = 0.0
    for v in seq:
        dt_drive = T[u][v] + (overhead - 1.0)
        de_total = E[u][v] + rules["sample_cost"]
        dt_total = dt_drive + 1.0
        gain = solar_sum(t, t + dt_total, eff) - dt_total * rules["idle_cost"]
        next_bat = min(98.0, bat) + gain - de_total
        if next_bat < min_bat_floor:
            deficit = min_bat_floor - next_bat
            tk = min(420, int(t + dt_total * 0.5))
            net_rate = max(0.4, SOLAR_UNIT[tk] * eff - rules["idle_cost"])
            w = deficit / net_rate
            total_wait += w
            dt_total += w
            gain = solar_sum(t, t + dt_total, eff) - dt_total * rules["idle_cost"]
            next_bat = min(98.0, bat) + gain - de_total
        bat = min(98.0, next_bat)
        samp = t + dt_total
        dl = nodes[v]["deadline_tick"]
        if dl is None or samp <= dl - dl_margin:
            score += nodes[v]["value"]
        else:
            score += nodes[v]["late_value"]
        t = samp
        u = v
    dt_ret = T[u][0]
    de_ret = E[u][0]
    gain = solar_sum(t, t + dt_ret, eff) - dt_ret * rules["idle_cost"]
    next_bat = min(98.0, bat) + gain - de_ret
    if next_bat < min_bat_floor:
        deficit = min_bat_floor - next_bat
        tk = min(420, int(t + dt_ret * 0.5))
        net_rate = max(0.4, SOLAR_UNIT[tk] * eff - rules["idle_cost"])
        w = deficit / net_rate
        total_wait += w
        dt_ret += w
    ret = t + dt_ret
    over = max(0.0, ret - max_ret)
    return score - 0.001 * ret - 2.0 * over, score, ret, total_wait, next_bat

def local_search_eco(seq, eff=0.85, max_ret=388.0):
    best = list(seq)
    best_obj, _, _, _, _ = eval_eco(best, eff=eff, max_ret=max_ret)
    for _ in range(15):
        improved = False
        for i in range(len(best)):
            cand = best[:i] + best[i+1:]
            obj, _, _, _, _ = eval_eco(cand, eff=eff, max_ret=max_ret)
            if obj > best_obj + 1e-6:
                best, best_obj, improved = cand, obj, True
                break
        if improved:
            continue
        for i in range(len(best)):
            v = best[i]
            rem = best[:i] + best[i+1:]
            for j in range(len(rem) + 1):
                if j == i:
                    continue
                cand = rem[:j] + [v] + rem[j:]
                obj, _, _, _, _ = eval_eco(cand, eff=eff, max_ret=max_ret)
                if obj > best_obj + 1e-6:
                    best, best_obj, improved = cand, obj, True
                    break
            if improved:
                break
        if improved:
            continue
        for i in range(len(best)):
            for j in range(i + 1, len(best)):
                cand = best[:i] + list(reversed(best[i:j+1])) + best[j+1:]
                obj, _, _, _, _ = eval_eco(cand, eff=eff, max_ret=max_ret)
                if obj > best_obj + 1e-6:
                    best, best_obj, improved = cand, obj, True
                    break
            if improved:
                break
        if improved:
            continue
        in_tour = set(best)
        for v in range(1, N):
            if v in in_tour:
                continue
            for j in range(len(best) + 1):
                cand = best[:j] + [v] + best[j:]
                obj, _, _, _, _ = eval_eco(cand, eff=eff, max_ret=max_ret)
                if obj > best_obj + 1e-6:
                    best, best_obj, improved = cand, obj, True
                    break
            if improved:
                break
        if improved:
            continue
        for i in range(len(best)):
            for v in range(1, N):
                if v in in_tour:
                    continue
                cand = best[:i] + [v] + best[i+1:]
                obj, _, _, _, _ = eval_eco(cand, eff=eff, max_ret=max_ret)
                if obj > best_obj + 1e-6:
                    best, best_obj, improved = cand, obj, True
                    break
            if improved:
                break
        if not improved:
            break
    return best

for eff in [0.80, 0.90, 1.00]:
    random.seed(42)
    best_seq = []
    best_obj = -1e9
    starts = [
        [id_to_idx[x] for x in ["t7", "t19", "t29", "t9", "t16", "t26", "t15", "t20", "t22", "t10", "t18", "t27", "t36", "t14", "t4", "t13", "t8", "t1", "t25", "t12", "t34", "t33", "t32", "t3"]],
        [id_to_idx[x] for x in ["t32", "t33", "t34", "t12", "t25", "t28", "t1", "t13", "t8", "t17", "t4", "t14", "t36", "t27", "t18", "t10", "t22", "t20", "t26", "t15", "t16", "t9", "t3"]],
        [id_to_idx[x] for x in ["t38", "t6", "t23", "t31", "t11", "t2", "t30", "t8", "t13", "t4", "t17", "t14", "t36", "t1", "t28", "t25", "t12", "t34", "t33", "t32", "t3"]],
    ]
    for s in starts:
        c = local_search_eco(s, eff=eff)
        obj, sc, ret, w, fb = eval_eco(c, eff=eff)
        if obj > best_obj:
            best_obj, best_seq = obj, c
    cur = list(best_seq)
    for it in range(30):
        cand = list(cur)
        for _ in range(random.randint(2, 5)):
            if cand:
                cand.pop(random.randrange(len(cand)))
        unvis = [x for x in range(1, N) if x not in cand]
        for _ in range(random.randint(1, 3)):
            if unvis:
                v = random.choice(unvis)
                unvis.remove(v)
                cand.insert(random.randrange(len(cand) + 1), v)
        cand = local_search_eco(cand, eff=eff)
        obj, sc, ret, w, fb = eval_eco(cand, eff=eff)
        if obj > best_obj + 1e-6:
            best_obj, best_seq, cur = obj, cand, cand
        elif random.random() < 0.25:
            cur = cand
    obj, sc, ret, w, fb = eval_eco(best_seq, eff=eff)
    print(f"=== EFF {eff:.2f}: score={sc:.2f}, ret={ret:.1f}, wait={w:.1f}t, final_bat={fb:.1f}, count={len(best_seq)} ===")
    print("  Tour:", [nodes[x]["id"] for x in best_seq])

