class MissionAutopilot:
    """Closed-loop controller managing telemetry, EKF state prediction, tour replanning, and uplink commands."""

    def __init__(self, rules: Dict[str, Any], world: Dict[str, Any], initial_packets: List[Dict[str, Any]]) -> None:
        self.rules = rules
        self.world = world
        base = world["base"]
        self.surf = Surface(world["cell_m"], world["elevation_cm"], world["terrain"])
        self.est = StateEstimator(rules, self.surf, float(base[0]), float(base[1]))
        self.nav = NavigatorAndPlanner(rules, world, self.est)

        self.scheduled_cmds: Dict[int, Dict[str, Any]] = {}
        self.confirmed_sampled: Set[str] = set()
        self.pending_samples: Dict[int, str] = {}
        self.last_replan_tick = -999
        self.returning_to_base = False

        for pkt in initial_packets:
            self._ingest_packet(pkt)

        # Initial full tour optimization at tick 0
        self.nav.replan_tour(
            self.est.x,
            self.est.y,
            4.0,
            self.est.last_battery,
            self.confirmed_sampled,
            force_full_search=True,
        )

    def _ingest_packet(self, pkt: Dict[str, Any]) -> Tuple[bool, bool]:
        t = int(pkt["tick"])
        for tid in pkt.get("sampled_targets", []):
            self.confirmed_sampled.add(tid)

        had_discovery = False
        for ev in pkt.get("events", []):
            if "discover" in str(ev).lower():
                had_discovery = True

        # Check if a scheduled drive at tick t failed to execute (e.g., cleared by safety stop)
        sched = self.scheduled_cmds.get(t)
        if sched and sched["action"] == "drive" and float(pkt.get("wheel_odometry", 0.0)) == 0.0:
            # Queue was cleared at or before tick t
            for tk in list(self.scheduled_cmds.keys()):
                if tk >= t:
                    self.scheduled_cmds.pop(tk, None)
                    self.pending_samples.pop(tk, None)

        safety_stop = self.est.process_packet(pkt)
        if safety_stop:
            for tk in list(self.scheduled_cmds.keys()):
                if tk > t:
                    self.scheduled_cmds.pop(tk, None)
                    self.pending_samples.pop(tk, None)

        # Clean up pending samples whose telemetry has arrived
        for tk in list(self.pending_samples.keys()):
            if tk <= self.est.last_tick:
                self.pending_samples.pop(tk, None)

        return had_discovery, safety_stop

    def decide_command_for_tick(
        self, current_tick: int, new_packets: List[Dict[str, Any]], latest_targets: Optional[List[Dict[str, Any]]] = None
    ) -> Dict[str, Any]:
        """Ingest new telemetry and return the command to uplink for execution at current_tick + delay_ticks + 1."""
        need_replan = False
        was_solar_known = self.est.solar_eff_known

        for pkt in new_packets:
            disc, stop = self._ingest_packet(pkt)
            if disc or stop:
                need_replan = True

        if latest_targets is not None:
            if self.nav.update_targets(latest_targets):
                need_replan = True

        if not was_solar_known and self.est.solar_eff_known:
            need_replan = True

        exec_tick = current_tick + int(self.rules["delay_ticks"]) + 1
        px, py, pbat = self.est.predict_state(self.scheduled_cmds, exec_tick - 1)
        sampled_or_pending = self.confirmed_sampled | set(self.pending_samples.values())

        # Remove already sampled targets from front of tour
        self.nav.current_tour = [tid for tid in self.nav.current_tour if tid not in sampled_or_pending]

        if need_replan or (current_tick - self.last_replan_tick >= 12) or not self.nav.current_tour:
            if not self.returning_to_base:
                self.nav.replan_tour(
                    px,
                    py,
                    float(exec_tick),
                    pbat,
                    sampled_or_pending,
                    force_full_search=need_replan,
                )
                self.last_replan_tick = current_tick

        # Check if we must head back to base now
        dt_base, de_base = self.nav.query_leg(px, py, "base", self.nav.base_x, self.nav.base_y, is_target=False)
        if exec_tick + dt_base * 1.07 + 2.0 >= 408.0 or not self.nav.current_tour:
            self.returning_to_base = True

        if self.returning_to_base:
            dist_base = math.hypot(self.nav.base_x - px, self.nav.base_y - py)
            # If well inside base_radius (4.0m), wait and let EKF refine position; only adjust if > 1.3m from base
            if dist_base <= 1.3:
                cmd = {"action": "wait"}
            else:
                wx, wy, is_final = self.nav.get_waypoint(px, py, "base", self.nav.base_x, self.nav.base_y)
                cmd_h, cmd_m, exp_e = self.nav.compute_drive_command(px, py, wx, wy, stop_at_waypoint=is_final)
                next_bat = min(self.rules["battery_capacity"], pbat + self.est.solar_gain(exec_tick)) - self.rules["idle_cost"] - exp_e
                if next_bat < 8.0:
                    cmd = {"action": "wait"}
                else:
                    cmd = {"action": "drive", "heading_deg": cmd_h, "metres": cmd_m}
            self.scheduled_cmds[exec_tick] = cmd
            return cmd

        # Target pursuit mode
        tid = self.nav.current_tour[0]
        t_obj = self.nav.targets_by_id[tid]
        tx, ty = float(t_obj["x"]), float(t_obj["y"])
        dist_t = math.hypot(tx - px, ty - py)
        appear_tick = t_obj.get("appear_tick") or 0

        if dist_t <= 1.25:
            if exec_tick < appear_tick:
                cmd = {"action": "wait"}
            else:
                next_bat = (
                    min(self.rules["battery_capacity"], pbat + self.est.solar_gain(exec_tick))
                    - self.rules["idle_cost"]
                    - self.rules["sample_cost"]
                )
                if next_bat < 10.0:
                    cmd = {"action": "wait"}
                else:
                    cmd = {"action": "sample"}
                    self.pending_samples[exec_tick] = tid
        else:
            wx, wy, is_final = self.nav.get_waypoint(px, py, tid, tx, ty)
            cmd_h, cmd_m, exp_e = self.nav.compute_drive_command(px, py, wx, wy, stop_at_waypoint=is_final)
            next_bat = min(self.rules["battery_capacity"], pbat + self.est.solar_gain(exec_tick)) - self.rules["idle_cost"] - exp_e
            # Keep safe battery floor (14.0 during morning/midday, 11.0 late)
            bat_floor = 14.0 if exec_tick < 250 else 11.0
            if next_bat < bat_floor:
                cmd = {"action": "wait"}
            else:
                cmd = {"action": "drive", "heading_deg": cmd_h, "metres": cmd_m}

        self.scheduled_cmds[exec_tick] = cmd
        return cmd
